using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class KonstantyIldefonsGałczyński
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdy trzcina zaczyna płowieć, a żołądź większy w dąbrowie, znak, że lata złote nogi już się szykują do drogi.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ze wszystkich kobiet świata najpiękniejsza jest noc.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Niebo zimno patrzy w Niobe.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Nieforemna, niewesoła, dzień i noc nad brzegiem morza stoi w skałę przemieniona", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Bo biurokracja jest jak pełnia, co świeci prosto w twarz: tu jakiś druczek się wypełnia, a tu formularz masz.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Sobie sam nawarzy piwa, kto od życia się odrywa.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Droga pędzi z nami bez wytchnienia. Chciałbym i mój ślad na drogach ocalić od zapomnienia.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Garniemy się do muzyki, Muzyka to jest nasz festyn. Kochamy trąbki i smyki Obój, klarnet, klawesyn.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ile razem dróg przebytych? Ile ścieżek przedeptanych?", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ja chciałbym twoje serce ocalić od zapomnienia.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Myślę, że po to są wiersze, ich ruch ku sercu człowieka, by szerzej szła, coraz szerzej przez kontynenty jutrzenka…", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Nie jesteśmy, by spożywać urok świata, ale po to, by go tworzyć i przetaczać przez czasy jak skałę złotą.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Pochylony nad mym stołem we wschodzącej zorzy łunie ręce twoje opisuję, serce twoje opisuję; smak twych ust jak morwa cierpki i głosu pochmurną słodycz.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Twe oczy jak piękne świece, a w sercu źródło promienia.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Niechaj tam inni księgi piszą. Nawet niechaj im sława dźwięczy jak wieża studzwonna, ja ksiąg pisać nie umiem, a nie dbam o sławę – serwus, madonna.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wszystko, coś stracił, wszystko, coś zgubił, w Bachu, bracie, odnajdziesz.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wtedy dłoń twą wziąłem w dłonie moje, w oczach naszych wieczny blask zaświecił i przez świat obłąkany od wojen szliśmy razem jak dwoje dzieci.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wszystko jak sen wariata śniony nieprzytomnie.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Co słychać? Nic.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Nigdy nie trzymaj się wyniośle, coś z mrówki miej, nie pawia, a jeśli kto ma uszy ośle, to z nim się nie umawiaj.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "ZA ŻADNE GÓRY SREBRA NIE DAM SE WYJĄĆ ŻEBRA.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "A ja tobie bajki opowiadam, szeptów moich słuchasz bardzo rada.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "A ty mnie na wyspy szczęśliwe zawieź, wiatrem łagodnym włosy jak kwiaty rozwiej, zacałuj (…)", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "A u was nuda i bieda, myszy, deszcz i Polska.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Angelologia i dal.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Bo cóż, że skończyli szkoły, cóż, że w kieszeniach matury? Jeden z nich niewesoły, drugi ponury.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Były dwie siostry: noc i śmierć, Śmierć większa, a noc mniejsza. Noc była piękna jak sen, a śmierć, Śmierć była jeszcze piękniejsza", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Chcieliście Polski, no to ją macie.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ciemne olchy stoją na moczarze, rozsypuje się w mokradłach próchno. Ej, rozświstał się wiatr na fujarze, małe gwiazdki nad olchami zdmuchnął.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Cóż, człowiek pisze tak, jak może, Obywatelu Redaktorze.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Dużo motyli mi pokaż, serca motyli przybliż i przytul, myśli spokojne ponad wodami pochyl miłością.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Dzisiaj słońce jest żałobną chorągwią Umarł Stalin.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ech, mój Krakowie krakauerski, wypić by cię jak wino z dzbanka!", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ech, muzyka, muzyka, muzyka, spod smyka zielony kurz. Lecą gwiazdy zielone spod smyka, damy karo i bukiety róż.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdy ci się kiedyś przyśni na przykład gałązka wiśni, to wiedz, że to znaczy szczęście – bo wiśnia we śnie znaczy, że koniec twej rozpaczy i że będziesz szczęśliwy coraz częściej.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdy nawet wiosną będziesz sam, kiedy jaskółce Próżno będziesz tłumaczył to, co ci dolega, Gdy najcięższą godzinę wskaże tobie zegar, Odszukaj mnie – i znajdziesz leżącą na półce.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdy wieje wiatr historii, Ludziom jak pięknym ptakom Rosną skrzydła, natomiast Trzęsą się portki pętakom.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdybym miał jedenaście kapeluszy, pierwszy schowałbym w szafie, żeby się nie kurzył. Drugi nadałbym przez pocztę w postaci paczki. Trzeci byłby na drobnostki i drobiażdżki.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Gdybyś mnie kiedyś miała przestać kochać, nie mów mi tego. Bóg tego także nie czyni.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Głos twój? Wodotrysk orzeźwiający, dzwonki i dzwony; to woda mówi; to śmieszny koncert ptaków zielonych", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "I nigdy nie będziesz biała, i nigdy nie będziesz czerwona, zostaniesz biało-czerwona, jak wielka zorza szalona.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ja jestem noc czerwcowa, Królowa jaśminowa, Zapatrzcie się w moje ręce, Wsłuchajcie się w śpiewny chód.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ja jestem Polak, a Polak jest wariat, a wariat to lepszy gość (…)", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Jam jest nad mocz wyższy, jam jest metafizyk.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Jedna była – gdzie? Pod Tobrukiem, Druga była – hej! Pod Narwikiem, Trzecia była pod Monte Cassino. A każda jak zorza szalona, biało-czerwona…!", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Jest patos wielkich uczuć, patos szczerozłoty, i jest patos blagierski: środek na wymioty.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Jeśli ogórek nie śpiewa, i to o żadnej porze, to widać z woli nieba prawdopodobnie nie może.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Już kocham cię tyle lat, na przemian w mroku i w śpiewie, może to już jest osiem lat, a może dziewięć – nie wiem.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Kiedy się wypełniły dni i przyszło zginąć latem, prosto do nieba czwórkami szli żołnierze z Westerplatte A lato było piękne tego roku", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Kochanie moje, kochanie, dobranoc, już jesteś senna – i widzę Twój cień na ścianie, i noc jest taka wiosenna.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Koń by też pisał wiersze, gdyby mu dać sto złotych, też miałby aspiracje, ambicje i tęsknoty.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Kiedy umrę i łopaty stukną, potem trawa porośnie na grobie, jako księżyc wrócę pod twe okno, będę bajki opowiadał tobie.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Mchy mówiły: „Ach, cóż za złocistość? Chyba będzie jaka uroczystość”. Dzięcioł z dębem rozmawiał znacząco, że się cudo zdarzyło na łące.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Mnie idiota? Od idioty? Sam idiota. Idiociński (…)", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Może na skrzypcach wygram Wiatr i pochyłą ulicę I noc, co taka niezwykła", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Mój panie, śmierć to rzecz prosta.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Mówisz, że cię miłość mierzi – zmierź mnie sobie, wołam, zmierź!", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Na Żoliborzu są ulice takie śliczne, Takie topole, a w topolach taki wiatr, Gdy przyjdzie wieczór, Świecą światła elektryczne. I tak mi dobrze, jakbym miał osiem lat.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Najlepsze te małe kina, gdzie wszystko się zapomina…", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Nawet wielbłąd gwizdnąłby na pustynię, gdyby mu, jak Boyowi, dać przednich wódek skrzynię", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Nie wystarczy pokochać, trzeba jeszcze umieć tę miłość przenieść przez całe życie.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "No, w raju, jak to w raju, zielono i wesoło, obiady, gadu-gadu, wieczerze i tak w koło.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Noc plus księżyc – to noc księżycowa.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "O Dzikiej Róży droga śpiewa pieśń i śmieje się, złoty znacząc ślad… Dzika Różo! Świecisz przez mrok. Dzika różo! Słyszysz mój krok? Idę – twój zakochany wiatr.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "O Radości, iskro bogów, kwiecie elizejskich cór, święta, na twym świętym progu staje nasz natchniony chór.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ona umarła potem z miłości, z owej tęsknoty i samotności. Ale że miłość to wielka siła, miłość po śmierci ich połączyła.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "O, zielony Konstanty, o, srebrna Natalio! Cała wasza wieczerza dzbanuszek z konwalią.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ojczyzną moją jest muzyka. A ty jesteś jak nuta rzewna, z którą na ustach, po latach, wraca się w muzykę jak do domu.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ona mi pierwsza pokazała księżyc i pierwszy śnieg na świerkach, i pierwszy deszcz.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "– Patrz, Kościuszko, na nas z nieba! – raz Polak skandował i popatrzył nań Kościuszko, i się zwymiotował.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Pieniądze? Jak ćmy się rozlecą. Sława? Nieraz płakał, kto cię miał. Przyjaźń? Szukaj jej ze świecą nocą, na wietrze, wśród skał.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Po cholerę toto żyje?", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Pod lewą powieką ukrywam pompkę wzruszenia.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Potem świecznik nagle cienie zmylił, żeśmy sądzili, że jesteśmy w Sewilli, jaka Sewilla?! To Katowice w zamieć.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Pyłem księżycowym być na twoich stopach wiatrem przy twej wstążce, mlekiem w twoim kubku, papierosem w ustach, ścieżką pośród chabrów, ławką, gdzie spoczywasz, książką którą czytasz.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Sensacja niesłychana: pani zdradziła pana. I zostały na biurku te słowa: – Drogi Jurku, przebacz. Jadę przez Kielce. Fatum. Zupa w butelce.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Sława, sława kolczykom Izoldy.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Słuchajcie – to dziecko nuci W czarodziejskim pudełku skrzypiec.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Sztuka jest wieczną wiosną. Sztuka jest ciepłym wiatrem, od którego śniegi topnieją.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Tak to nadobne grono radziło unisono w śmiertelnej sali. A że lico miał bladsze orzekli: – Pewnie nadszedł koniec kanalii.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Tu nie pomoże nic… a cóż ja znaczę! ten sam sen, ten sam błysk, srebrne akacje", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Tyś jest rewolta i klęska, i mgła, a ja to twe rzęsy i loki.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ukochany kraj, umiłowany kraj, ukochane i miasta, i wioski, ukochany kraj, umiłowany kraj, ukochany, jedyny, nasz, polski.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Ukochany kraj, Umiłowany kraj, Ukochany, jedyny, nasz, polski. Ukochany kraj, Umiłowany kraj, Ukochana i ziemia, i nazwa (…).", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Warszawski wiatr na Starówce i Mariensztacie Warszawski wiatr wy się w nim jak ja zakochacie Jemu równego nie ma na Freta i Bema i jak szeroka ziemia pędzi warszawski wiatr…", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wciąż uciekamy. Z miasta do miasta. Inteligenci. Tęskniąca nacja. Ginąca klasa. Mali, zmarznięci.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "We śnie jesteś moja i pierwsza, we śnie jestem pierwszy dla ciebie. Rozmawiamy o kwiatach i wierszach, psach na ziemi i ptakach na niebie.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "wielkim, bezkresnym wachlarzem wachluje nas chłopiec nieduży, szmaragdy w uszach ma, on jest Murzyn, a my nazywamy go Nocą.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wszak miłość jest cierpieniem, nie fraszką jałową.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Wszystkie instrumenty nie wyrażą tego, co w sercu zamknięte: i flet jest kaleką i organ i arfa, śpiewają nietęgo (…).", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Za duży wiatr na moją wełnę.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "ZACZAROWANA DOROŻKA ZACZAROWANY DOROŻKARZ ZACZAROWANY KOŃ. Z Wieży Mariackiej światłem prószy. A koń, wyobraźcie sobie, miał autentyczne uszy.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Zadrżałem. Druga w nocy. Pocztylion stał jak pika. I urosły mi włosy do samego świecznika: ZACZAROWANA DOROŻKA? ZACZAROWANY DOROŻKARZ? ZACZAROWANY KOŃ?", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Zapachniały zefiry Brzękły potrójne liry Pierzchnęła tłuszcza Serce alkoholowe Unieśli aniołowie Na złotych bluszczach.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Zapytajcie Artura, daję słowo: nie kłamię, ale było jak ulał sześć słów w tym telegramie: ZACZAROWANA DOROŻKA ZACZAROWANY DOROŻKARZ ZACZAROWANY KOŃ.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Życie jest zawsze takie, że jest się w nim, moje złoto, albo zimnym łajdakiem, albo natchnionym idiotą.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Życie nas nie złączyło, to nas śmierć połączy, o, Mario, Mario moja, najwspanialsza nogo! To cóż, że mąż twój na nas patrzy dosyć wrogo, niech patrzy, my dziś jeszcze wysiądziemy w Łomży.", Author = "Konstanty Ildefons Gałczyński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Konstanty_Ildefons_Gałczyński", Text = "Kochajcie wróbelka dziewczęta, Kochajcie do jasnej cholery!", Author = "Konstanty Ildefons Gałczyński" },
        };
    }
}